// Insert inserts the record into the database
func (t *GeneralPostingSetup) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, GeneralPostingSetupTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Gen_bus_posting_group,
		t.Gen_prod_posting_group,
		t.Sales_account,
		t.Sales_line_disc_account,
		t.Sales_inv_disc_account,
		t.Sales_payment_disc_account,
		t.Purch_account,
		t.Purch_line_disc_account,
		t.Purch_inv_disc_account,
		t.Purch_payment_disc_account,
		t.Cogs_account,
		t.Inventory_adjmt_account,
		t.Project_sales_adjmt_account,
		t.Project_cost_adjmt_account,
		t.Sales_credit_memo_account,
		t.Purch_credit_memo_account,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (gen_bus_posting_group, gen_prod_posting_group, sales_account, sales_line_disc_account, sales_inv_disc_account, sales_payment_disc_account, purch_account, purch_line_disc_account, purch_inv_disc_account, purch_payment_disc_account, cogs_account, inventory_adjmt_account, project_sales_adjmt_account, project_cost_adjmt_account, sales_credit_memo_account, purch_credit_memo_account) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (gen_bus_posting_group, gen_prod_posting_group) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert General_Posting_Setup: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(GeneralPostingSetupTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *GeneralPostingSetup) InsertAll(records []*GeneralPostingSetup, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Gen_bus_posting_group,
			r.Gen_prod_posting_group,
			r.Sales_account,
			r.Sales_line_disc_account,
			r.Sales_inv_disc_account,
			r.Sales_payment_disc_account,
			r.Purch_account,
			r.Purch_line_disc_account,
			r.Purch_inv_disc_account,
			r.Purch_payment_disc_account,
			r.Cogs_account,
			r.Inventory_adjmt_account,
			r.Project_sales_adjmt_account,
			r.Project_cost_adjmt_account,
			r.Sales_credit_memo_account,
			r.Purch_credit_memo_account,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, GeneralPostingSetupTableName)
	columns := []string{"gen_bus_posting_group", "gen_prod_posting_group", "sales_account", "sales_line_disc_account", "sales_inv_disc_account", "sales_payment_disc_account", "purch_account", "purch_line_disc_account", "purch_inv_disc_account", "purch_payment_disc_account", "cogs_account", "inventory_adjmt_account", "project_sales_adjmt_account", "project_cost_adjmt_account", "sales_credit_memo_account", "purch_credit_memo_account"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *GeneralPostingSetup) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("gen_bus_posting_group") {
			keyChanged = true
		}
		if t.hasFieldChanged("gen_prod_posting_group") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, GeneralPostingSetupTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("gen_bus_posting_group") {
			setClauses = append(setClauses, "gen_bus_posting_group = ?")
			values = append(values, t.Gen_bus_posting_group)
		}
		if t.hasFieldChanged("gen_prod_posting_group") {
			setClauses = append(setClauses, "gen_prod_posting_group = ?")
			values = append(values, t.Gen_prod_posting_group)
		}
		if t.hasFieldChanged("sales_account") {
			setClauses = append(setClauses, "sales_account = ?")
			values = append(values, t.Sales_account)
		}
		if t.hasFieldChanged("sales_line_disc_account") {
			setClauses = append(setClauses, "sales_line_disc_account = ?")
			values = append(values, t.Sales_line_disc_account)
		}
		if t.hasFieldChanged("sales_inv_disc_account") {
			setClauses = append(setClauses, "sales_inv_disc_account = ?")
			values = append(values, t.Sales_inv_disc_account)
		}
		if t.hasFieldChanged("sales_payment_disc_account") {
			setClauses = append(setClauses, "sales_payment_disc_account = ?")
			values = append(values, t.Sales_payment_disc_account)
		}
		if t.hasFieldChanged("purch_account") {
			setClauses = append(setClauses, "purch_account = ?")
			values = append(values, t.Purch_account)
		}
		if t.hasFieldChanged("purch_line_disc_account") {
			setClauses = append(setClauses, "purch_line_disc_account = ?")
			values = append(values, t.Purch_line_disc_account)
		}
		if t.hasFieldChanged("purch_inv_disc_account") {
			setClauses = append(setClauses, "purch_inv_disc_account = ?")
			values = append(values, t.Purch_inv_disc_account)
		}
		if t.hasFieldChanged("purch_payment_disc_account") {
			setClauses = append(setClauses, "purch_payment_disc_account = ?")
			values = append(values, t.Purch_payment_disc_account)
		}
		if t.hasFieldChanged("cogs_account") {
			setClauses = append(setClauses, "cogs_account = ?")
			values = append(values, t.Cogs_account)
		}
		if t.hasFieldChanged("inventory_adjmt_account") {
			setClauses = append(setClauses, "inventory_adjmt_account = ?")
			values = append(values, t.Inventory_adjmt_account)
		}
		if t.hasFieldChanged("project_sales_adjmt_account") {
			setClauses = append(setClauses, "project_sales_adjmt_account = ?")
			values = append(values, t.Project_sales_adjmt_account)
		}
		if t.hasFieldChanged("project_cost_adjmt_account") {
			setClauses = append(setClauses, "project_cost_adjmt_account = ?")
			values = append(values, t.Project_cost_adjmt_account)
		}
		if t.hasFieldChanged("sales_credit_memo_account") {
			setClauses = append(setClauses, "sales_credit_memo_account = ?")
			values = append(values, t.Sales_credit_memo_account)
		}
		if t.hasFieldChanged("purch_credit_memo_account") {
			setClauses = append(setClauses, "purch_credit_memo_account = ?")
			values = append(values, t.Purch_credit_memo_account)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "sales_account = ?")
		values = append(values, t.Sales_account)
		setClauses = append(setClauses, "sales_line_disc_account = ?")
		values = append(values, t.Sales_line_disc_account)
		setClauses = append(setClauses, "sales_inv_disc_account = ?")
		values = append(values, t.Sales_inv_disc_account)
		setClauses = append(setClauses, "sales_payment_disc_account = ?")
		values = append(values, t.Sales_payment_disc_account)
		setClauses = append(setClauses, "purch_account = ?")
		values = append(values, t.Purch_account)
		setClauses = append(setClauses, "purch_line_disc_account = ?")
		values = append(values, t.Purch_line_disc_account)
		setClauses = append(setClauses, "purch_inv_disc_account = ?")
		values = append(values, t.Purch_inv_disc_account)
		setClauses = append(setClauses, "purch_payment_disc_account = ?")
		values = append(values, t.Purch_payment_disc_account)
		setClauses = append(setClauses, "cogs_account = ?")
		values = append(values, t.Cogs_account)
		setClauses = append(setClauses, "inventory_adjmt_account = ?")
		values = append(values, t.Inventory_adjmt_account)
		setClauses = append(setClauses, "project_sales_adjmt_account = ?")
		values = append(values, t.Project_sales_adjmt_account)
		setClauses = append(setClauses, "project_cost_adjmt_account = ?")
		values = append(values, t.Project_cost_adjmt_account)
		setClauses = append(setClauses, "sales_credit_memo_account = ?")
		values = append(values, t.Sales_credit_memo_account)
		setClauses = append(setClauses, "purch_credit_memo_account = ?")
		values = append(values, t.Purch_credit_memo_account)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["gen_bus_posting_group"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Gen_bus_posting_group)
	}
	if old, ok := t.oldValues["gen_prod_posting_group"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Gen_prod_posting_group)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND gen_bus_posting_group = ? AND gen_prod_posting_group = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify General_Posting_Setup: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

